def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = 4

    row_bands = []
    start = 0
    for r in range(h):
        if all(v == sep for v in grid[r]):
            if start < r:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))

    col_bands = []
    start = 0
    for c in range(w):
        if all(grid[r][c] == sep for r in range(h)):
            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))

    # Find the band-sized tile containing the most non-background cells.
    background = max(set(v for row in grid for v in row), key=lambda x: sum(row.count(x) for row in grid))
    source = None
    best = -1
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            score = sum(grid[r][c] != background
                        for r in range(r0, r1) for c in range(c0, c1))
            if score > best:
                best = score
                source = [[grid[r][c] for c in range(c0, c1)] for r in range(r0, r1)]

    out = [row[:] for row in grid]
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            for dr in range(r1 - r0):
                for dc in range(c1 - c0):
                    out[r0 + dr][c0 + dc] = source[dr][dc]
    return out
